@font-face{font-family:'Mignon';src:url(data:font/woff;base64,) format('woff');font-display:swap}
:root{
  color-scheme:dark;
  --bg:#08050a; --bone:#d8ceb6; --rose:#e9a3bd; --blood:#8a1738; --dim:#8c8372;
  box-sizing:border-box; padding-top:env(safe-area-inset-top,0px); padding-bottom:env(safe-area-inset-bottom,0px);
}
*{box-sizing:border-box}
html{scroll-padding-top:env(safe-area-inset-top,0px)}
body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 50% 30%,#1a0d17 0,var(--bg) 65%);color:var(--bone);font-family:'Mignon','Courier New',Courier,monospace;font-size:1.05rem;line-height:1.6;overflow-x:hidden}
.frame{max-width:860px;margin:1.5rem auto;padding:1.5rem 1.25rem 2rem;border:64px solid transparent;border-image:url(data:image/png;base64,) 16.5% / 64px round;position:relative;text-align:center}
.crest{font-size:2rem;color:var(--rose);letter-spacing:.6em;margin-bottom:1rem;padding-left:.6em}
.portal{width:min(560px,100%);aspect-ratio:704/432;margin:0 auto 1rem;position:relative;container-type:inline-size;background:url(data:image/gif;base64,) center/100% 100% no-repeat}
.portal .in{position:absolute;left:50%;top:54%;transform:translate(-50%,-50%);width:24%;text-align:center;display:flex;flex-direction:column;align-items:center;gap:.1em}
.portal .cross{font-size:7cqw;line-height:1;color:var(--bone)}
.portal .t{font-family:'UnifrakturCook','Old English Text MT',serif;font-size:9.5cqw;line-height:1}
.portal .ap{font-size:2.8cqw;color:var(--rose)}
.portal .s{font-size:2.3cqw;color:var(--rose);line-height:1.2}
.sub{font-style:italic;color:var(--rose);margin:0}
h1{font-family:'UnifrakturCook','Old English Text MT',serif;font-weight:700;font-size:clamp(3rem,13vw,6rem);line-height:1;margin:.2rem 0 .8rem}
.intro{max-width:32rem;margin:0 auto 2.5rem;color:var(--bone)}
.table{text-align:left;border:3px double var(--bone);padding:1.2rem 1.2rem .6rem;max-width:720px;margin:0 auto}
.head,.row{display:flex;align-items:baseline;gap:.6rem}
.head{font-weight:700;letter-spacing:.1em;font-size:.95rem;padding-bottom:.6rem;color:var(--rose);justify-content:space-between}
.row{text-decoration:none;color:var(--bone);padding:.55rem .3rem;cursor:none;transition:background .2s,color .2s}
.row .n{font-family:'UnifrakturCook',serif;font-size:1.7rem;line-height:1}
.row .lead{flex:1;border-bottom:1px dotted var(--dim);transform:translateY(-.3em);min-width:1rem}
.row .st{font-style:italic;color:var(--dim);font-size:1rem;white-space:nowrap}
.row:hover,.row:focus-visible{background:var(--blood);color:#fff}
.row:hover .st,.row:focus-visible .st{color:var(--rose)}
.row:focus-visible{outline:2px dashed var(--rose);outline-offset:2px}
.row .lead{min-width:1rem}
.row .n{font-size:1.4rem}
[hidden]{display:none!important}
.ttl{color:inherit;text-decoration:none}
.about{max-width:720px;margin:0 auto;text-align:left;display:grid;grid-template-columns:170px 1fr 150px;border:3px double var(--bone);background:rgba(138,23,56,.08)}
.about>div{padding:1rem}
.about .main{border-left:1px dashed var(--dim);border-right:1px dashed var(--dim)}
.portrait{aspect-ratio:3/4;border-radius:18px;border:1px solid var(--rose);background:radial-gradient(circle at 50% 40%,#2a1220,#0c070d 75%);display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--rose);font-size:.85rem;text-align:center;gap:.3rem}
.portrait b{font-size:2.4rem;font-weight:400;color:var(--bone)}
.pbtns{display:flex;justify-content:space-between;margin-top:.9rem}
.pbtn{width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#1c0f18;border:1px solid var(--dim);color:var(--bone);text-decoration:none;font-size:1.3rem;cursor:none;transition:background .2s}
.pbtn:nth-child(2){background:var(--rose);color:#2a1420}
.pbtn:hover,.pbtn:focus-visible{background:var(--blood);color:#fff;outline:none}
.about h2{font-family:'UnifrakturCook','Old English Text MT',serif;font-weight:700;font-size:2rem;line-height:1.1;margin:0}
.about .age{color:var(--rose);border-bottom:2px solid var(--blood);padding-bottom:.4rem;margin:.2rem 0 .8rem}
.blk{padding:.6rem 0;border-bottom:1px solid var(--dim)}
.blk:last-of-type{border-bottom:0}
.chip{display:inline-block;background:var(--rose);color:#2a1420;border-radius:6px;padding:0 .5rem;margin-right:.3rem;font-size:.9rem}
.blk cite{display:block;color:var(--dim);font-size:.9rem;font-style:normal;margin-top:.2rem}
.back{display:inline-block;margin-top:.8rem;color:var(--rose);text-decoration:none;border-bottom:1px dotted var(--rose);cursor:none}
.tile{border:1px dashed var(--dim);border-radius:18px;display:flex;align-items:center;justify-content:center;flex-direction:column;color:var(--dim);font-size:.8rem;text-align:center;margin-bottom:.8rem;background:rgba(233,163,189,.05)}
.tile b{font-size:1.8rem;font-weight:400;color:var(--rose)}
.t1{aspect-ratio:1/1}.t2{aspect-ratio:4/3}.t3{padding:.7rem;color:var(--rose);font-size:1.3rem;letter-spacing:.3em}
.interests-layout{max-width:720px;margin:0 auto;text-align:left;display:grid;grid-template-columns:minmax(0,1fr) 170px;border:3px double var(--bone);background:rgba(138,23,56,.08)}
.interests-copy,.interest-pictures{padding:1rem}
.interests-layout h2{font-family:'UnifrakturCook','Old English Text MT',serif;font-size:1.8rem;line-height:1.1;margin:0 0 .8rem}
.interest-tree{padding-left:1.4rem}
.interest-tree ul{padding-left:1.4rem;list-style-type:circle}
.interest-tree li{margin:.4rem 0}
.interest-pictures{border-left:1px dashed var(--dim)}
.interest-picture{display:block;margin:0 0 .8rem;padding:.5rem}
.picture-slot{aspect-ratio:1;display:flex;align-items:center;justify-content:center;color:var(--rose);background:rgba(233,163,189,.05);border:1px dashed var(--dim)}
.interest-picture figcaption{text-align:center;margin-top:.35rem}
@media (max-width:760px){.about{grid-template-columns:1fr}.about .main{border:0;border-top:1px dashed var(--dim);border-bottom:1px dashed var(--dim)}.portrait{aspect-ratio:4/3}}
@media (max-width:760px){.interests-layout{grid-template-columns:1fr}.interest-pictures{border-left:0;border-top:1px dashed var(--dim)}.interest-pictures>h2{grid-column:1/-1}.interest-pictures{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:.8rem}.interest-picture{margin:0}}
.row .d{color:var(--rose);font-size:.9rem;white-space:nowrap}
.menu{display:flex;flex-wrap:wrap;justify-content:center;gap:.3rem 1.6rem;margin:0 auto 2rem}
.menu a{font-family:'UnifrakturCook','Old English Text MT',serif;font-size:1.5rem;color:var(--bone);text-decoration:none;border-bottom:1px dotted var(--dim);cursor:none;transition:color .2s}
.menu a:hover,.menu a:focus-visible{color:var(--rose);outline:none}
.menu a.on{color:var(--rose);border-bottom-style:solid}
@media (max-width:520px){.row .d{display:none}.menu a{font-size:1.25rem}}
footer{margin-top:2rem;color:var(--dim);font-size:1rem}
footer b{color:var(--rose);font-weight:500}
#toast{position:fixed;left:50%;bottom:calc(1.5rem + env(safe-area-inset-bottom,0px));transform:translate(-50%,200%);background:var(--blood);color:#fff;padding:.6rem 1.3rem;border:1px solid var(--rose);transition:transform .25s;z-index:50}
#toast.show{transform:translate(-50%,0)}
.cur-on,.cur-on a{cursor:none}
#cur,#ring{position:fixed;left:0;top:0;pointer-events:none;z-index:100;display:none}
.cur-on #cur,.cur-on #ring{display:block}
#cur{width:26px;height:34px;margin:-6px 0 0 -13px}
#ring{width:36px;height:36px;margin:-18px 0 0 -18px;border:1.5px solid var(--rose);border-radius:50%;transition:width .2s,height .2s,margin .2s,background .2s}
#ring.big{width:64px;height:64px;margin:-32px 0 0 -32px;background:rgba(138,23,56,.4)}
.bit{position:fixed;pointer-events:none;z-index:99;color:var(--rose);font-size:16px;margin:-8px 0 0 -8px;animation:pop .8s ease-out forwards}
@keyframes pop{to{transform:translate(var(--dx),var(--dy)) rotate(90deg) scale(.3);opacity:0}}
@media (prefers-reduced-motion:reduce){.bit{display:none}*{transition:none!important}}
@media (max-width:520px){.portal .s{display:none}.frame{border-width:36px;border-image-width:36px;margin:.5rem;padding:1rem .5rem 1.5rem}.row .st{font-size:.85rem}}